const container=document.querySelector("#category-articles"),category=document.querySelector('meta[name="notes-category"]')?.content||"";function formatDate(e){if(!e)return"";const t=new Date(e);return Number.isNaN(t.getTime())?"":t.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}function renderArticles(e){if(!e||0===e.length)return void(container.innerHTML='<p class="result-placeholder" style="grid-column:1/-1;text-align:center;padding:40px 0;color:var(--section-muted);">暂无文章。</p>');let t="";for(const n of e){const e=formatDate(n.createdAt);t+=`\n      <a class="section-lab-panel" href="/notes/article/?id=${n.id}" style="text-decoration:none;color:inherit;">\n        <p class="section-lab-label">${n.category}</p>\n        <h2>${n.title}</h2>\n        ${e?`<p style="font-size:0.82rem;color:var(--section-muted);margin-top:8px;">${e}</p>`:""}\n      </a>`}container.innerHTML=t}async function load(){if(category)try{const e=await fetch(`/api/notion/articles?public=true&module=%E7%AC%94%E8%AE%B0&category=${encodeURIComponent(category)}`),t=await e.json();e.ok&&renderArticles(t.articles)}catch{container.style.display="none"}}load();